-- M1: several agents. Session ids are UUIDs generated by each agent, so session_id stays the primary key; the agent
-- column says which adapter a row belongs to. Existing rows came from Claude Code only.
ALTER TABLE sessions ADD COLUMN agent TEXT NOT NULL DEFAULT 'claude-code';
ALTER TABLE sessions ADD COLUMN pane_id TEXT;
ALTER TABLE session_transitions ADD COLUMN agent TEXT NOT NULL DEFAULT 'claude-code';
ALTER TABLE usage_entries ADD COLUMN agent TEXT NOT NULL DEFAULT 'claude-code';
CREATE INDEX ix_usage_agent_ts ON usage_entries(agent, ts);
